// CPR/First Aid Practice Test 4. Original questions written for Valus from the HOSA 2026–27 test plan,
// slightly harder than the sample items and covering different situations from Practice Tests 1–3.
import {q, mix} from './q.js';
const AHA_BLS='AHA Basic Life Support', AHA_FA='AHA Heartsaver First Aid', ARC_BLS='ARC Basic Life Support', ARC_FA='ARC First Aid/CPR/AED', DHO='Simmers, DHO: Health Science';
const GEN='General Concepts', CPR='BLS/CPR for Adults, Children and Infants', AED='AED for Adults, Children and Infants', ADV='CPR with Advanced Airway', RB='Mouth-to-Mouth/Rescue Breathing', CH='Relief of Choking';
const BASIC='Basic', MED='Medical Emergencies', INJ='Injury Emergencies', ENV='Environmental Emergencies';

export default {
 id:'cpr-first-aid-4',
 event:'CPR/First Aid',
 title:'Practice Test 4',
 subtitle:'Full-length Round One simulation',
 minutes:60,
 sources:'AHA and American Red Cross BLS and First Aid, and DHO: Health Science',
 plan:[
  {area:'Basic Life Support',weight:40,topics:[GEN,CPR,AED,ADV,RB,CH]},
  {area:'First Aid',weight:60,topics:[BASIC,MED,INJ,ENV]}
 ],
 questions:mix([
  q(GEN,'How does cardiac arrest differ from a heart attack?','The heart stops pumping effectively',['The heart muscle is always permanently damaged','Blood flow to the brain increases suddenly','The person always remains awake and talking'],'A','In a heart attack, a blocked artery starves heart muscle; in cardiac arrest, the heart stops pumping, often from an abnormal rhythm.',AHA_BLS),
  q(GEN,'In a resuscitation team, what is the main role of the team leader?','Assign roles and monitor the team’s work',['Perform every compression personally','Record the times of every drug given','Hold the bag-mask device the whole time'],'B','The leader organizes the team, assigns tasks, watches CPR quality and makes decisions while others carry out specific roles.',AHA_BLS),
  q(GEN,'After CPR, an adult begins breathing normally but stays unresponsive. What should the rescuer do?','Place them in the recovery position and watch',['Keep giving compressions at the same rate','Remove the AED pads and leave the scene','Sit the person upright against a wall'],'C','Leave the AED attached, turn the person onto the side to protect the airway and keep monitoring breathing until EMS arrives.',AHA_BLS),
  q(GEN,'How likely is a rescuer to catch an infection while giving CPR?','The risk is very low',['The risk is higher than 1 in 2','It is certain without gloves','It depends only on the person’s age'],'D','Disease transmission during CPR is extremely rare; barrier devices reduce the small remaining risk.',ARC_BLS),
  q(CPR,'About how deep should compressions be for a 4-year-old child?','About 2 inches (5 cm)',['About 1 inch (2.5 cm)','About 3 inches (7.5 cm)','About ½ inch (1 cm)'],'A','For children, compress at least one-third the depth of the chest, about 2 inches; for infants about 1½ inches.',AHA_BLS),
  q(CPR,'Why should the compressor keep the arms straight with shoulders directly over the hands?','It uses body weight and limits fatigue',['It keeps the rescuer’s back from bending','It lets the rescuer check the pulse','It makes rescue breaths easier to give'],'B','Pushing straight down from the shoulders uses the upper body’s weight, giving deeper compressions with less tiring.',ARC_BLS),
  q(CPR,'A healthcare provider suspects a spinal injury in an unresponsive adult. How should the airway be opened first?','With a jaw-thrust maneuver',['With a strong head-tilt chin-lift','By turning the head to the side','By lifting the shoulders off the ground'],'C','The jaw thrust opens the airway with less neck movement; use head tilt–chin lift if the jaw thrust does not open the airway.',AHA_BLS),
  q(CPR,'An adult in cardiac arrest is found lying in a soft bed at home. What should rescuers do?','Move the person to a firm, flat surface',['Do compressions on the bed as is','Prop the person up with pillows','Wait for EMS to move the person'],'D','A soft surface absorbs much of the force, so the person should be moved to the floor or a firm surface if it can be done quickly.',ARC_BLS),
  q(CPR,'How should an infant’s head be positioned to open the airway?','In a neutral, “sniffing” position',['Tilted back as far as it will go','Turned fully to one side','Bent forward with the chin down'],'A','An infant’s airway is soft and can kink if the head is tilted too far, so a slight tilt to a neutral position is used.',AHA_BLS),
  q(CPR,'How may a rescuer give compressions to a small child?','With one or two hands on the breastbone',['With two fingers only, at the neck','With the heel of the foot on the chest','With both thumbs on the stomach'],'B','For a child, use one hand or two hands on the lower half of the sternum, whichever gives the proper depth.',AHA_BLS),
  q(AED,'What is the purpose of a pediatric dose attenuator on an AED?','To lower the shock energy for a child',['To raise the shock energy for a child','To speed up rhythm analysis','To record the child’s heart rate'],'C','The attenuator reduces the energy delivered, which is preferred for infants and children under 8 when available.',AHA_BLS),
  q(AED,'An adult in cardiac arrest lies on metal bleachers. Can the AED be used?','Yes, if no one touches the person',['No, never on a metal surface','Only after pouring water on the metal','Only with pediatric pads'],'D','An AED can be used on metal or snow as long as the pads do not touch the metal and everyone stays clear during the shock.',ARC_BLS),
  q(AED,'An AED arrives at the scene of an adult in cardiac arrest. What is the first step?','Turn the AED on',['Shave the entire chest','Check the battery voltage','Remove the person’s shoes'],'A','Turning the AED on starts its voice prompts, which guide rescuers through pad placement and analysis.',AHA_BLS),
  q(AED,'A woman in cardiac arrest has a body piercing where an AED pad should go. What should the rescuer do?','Avoid placing a pad directly on it',['Remove the piercing with pliers first','Skip using the AED entirely','Place both pads on the piercing'],'B','Metal jewelry under a pad can cause burns or reduce the shock; shift the pad slightly so it does not sit over the piercing.',ARC_BLS),
  q(ADV,'During CPR with an advanced airway, end-tidal CO₂ stays below 10 mm Hg. What does this suggest?','Compressions may be inadequate',['Return of spontaneous circulation','The patient is breathing too fast','The airway is in the stomach for sure'],'C','Low EtCO₂ during CPR reflects poor blood flow to the lungs; rescuers should improve compression quality.',AHA_BLS),
  q(ADV,'Before an advanced airway is placed, how do two rescuers coordinate adult CPR?','30 compressions, then pause for 2 breaths',['Continuous compressions with 1 breath every 6 s','15 compressions, then pause for 2 breaths','5 compressions, then pause for 1 breath'],'D','Without an advanced airway, adults receive cycles of 30:2 even with two rescuers; continuous compressions begin once an advanced airway is in.',AHA_BLS),
  q(RB,'A person with a pulse needs rescue breaths, but the mouth is badly injured. Which method can be used?','Mouth-to-nose breathing',['Breathing into one ear','Chest compressions only','Blowing air across the face'],'A','Close the mouth and breathe into the nose; mouth-to-nose ventilation works when the mouth cannot be used.',ARC_BLS),
  q(RB,'A person who breathes through a neck opening after a laryngectomy needs rescue breaths. How are they given?','Mouth-to-stoma',['Mouth-to-mouth with the stoma open','Mouth-to-nose only','Breaths are never given'],'B','People with a laryngectomy breathe through the stoma, so breaths are given directly into it, ideally with a barrier.',ARC_BLS),
  q(CH,'An adult is choking but coughing forcefully and can speak. What should the rescuer do?','Encourage them to keep coughing',['Give abdominal thrusts right away','Give 5 back blows at once','Perform a blind finger sweep'],'C','A mild obstruction is best cleared by the person’s own coughing; act only if the obstruction becomes severe.',ARC_FA),
  q(CH,'An infant is choking and cannot cry or cough. Which sequence is used?','5 back blows, then 5 chest thrusts',['5 abdominal thrusts, then 5 back blows','2 rescue breaths, then 30 compressions','10 back blows, then a finger sweep'],'D','Alternate 5 back blows with 5 chest thrusts until the object comes out or the infant becomes unresponsive.',AHA_FA),
  q(BASIC,'An off-duty nurse stops to help at a car crash. When does a legal duty to act usually apply?','When a job requires giving care',['Whenever a person has any training','Only after the nurse has started CPR','Only when police order the nurse'],'A','Professional rescuers on duty have a duty to act; most off-duty bystanders do not, though some states have duty-to-assist laws.',ARC_FA),
  q(BASIC,'Which is a sign rather than a symptom?','A rash the first aider can see',['Nausea the person describes','A headache the person reports','Dizziness the person feels'],'B','Signs are observed or measured by the rescuer; symptoms are what the person feels and reports.',DHO),
  q(BASIC,'What is the normal resting breathing rate for an adult?','12–20 breaths per minute',['4–8 breaths per minute','30–40 breaths per minute','50–60 breaths per minute'],'C','Rates below 12 or above 20 at rest may indicate a problem; children and infants normally breathe faster.',DHO),
  q(BASIC,'When calling 911, what information is most important to give first?','The exact location of the emergency',['The person’s insurance company','Your own date of birth','The person’s full medical history'],'D','Dispatchers need the location first so help can be sent even if the call is cut off.',AHA_FA),
  q(BASIC,'Fingers below a new bandage turn pale, cold and numb. What does this mean?','The bandage is too tight',['The wound is healing well','The bleeding has stopped','The person needs more bandages'],'A','A bandage that cuts off circulation must be loosened; check fingers or toes for color, warmth and feeling after bandaging.',ARC_FA),
  q(BASIC,'Which are examples of bloodborne pathogens?','Hepatitis B, hepatitis C and HIV',['Influenza, measles and chickenpox','Strep throat, pinkeye and lice','Tuberculosis, mumps and colds'],'B','Bloodborne pathogens spread through contact with infected blood or body fluids, which is why gloves and barriers are used.',DHO),
  q(BASIC,'A person in shock is breathing and has no spinal injury. How should they be positioned?','Lying flat on their back',['Sitting upright in a chair','Standing to improve blood flow','Lying on the stomach with arms raised'],'C','Lying flat helps blood flow to vital organs; keep the person warm and do not give anything to eat or drink.',AHA_FA),
  q(MED,'A person with diabetes acts confused, and you are unsure whether blood sugar is high or low. They can swallow. What should you do?','Give sugar, such as juice or glucose tablets',['Give their insulin injection','Withhold all food and fluids','Have them exercise to lower sugar'],'D','Low blood sugar is more immediately dangerous; extra sugar will not cause serious harm if the sugar is actually high.',AHA_FA),
  q(MED,'A man has stroke signs that go away completely within 20 minutes. What should the first aider do?','Call 911 anyway',['Let him drive himself home','Tell him to rest and skip care','Give him two aspirin and leave'],'A','A transient ischemic attack is a warning sign of stroke; it needs emergency evaluation even if symptoms resolve.',AHA_FA),
  q(MED,'A person with a known heart condition has chest pain and carries prescribed nitroglycerin. What can a first aider do?','Help them take their own medicine',['Give them someone else’s nitroglycerin','Keep the medicine away from them','Have them walk around to ease pain'],'B','First aiders may help a person take their own prescribed medicine and should call 911 for chest pain.',ARC_FA),
  q(MED,'A college student who drank heavily is unresponsive but breathing. What should the first aider do?','Call 911 and use the recovery position',['Let them sleep it off on their back','Put them in a cold shower','Give them coffee to wake them'],'C','Alcohol poisoning can stop breathing and cause choking on vomit; call 911 and keep the airway open on the side.',AHA_FA),
  q(MED,'A teen has severe pain in the lower right abdomen with fever and vomiting. What should the first aider do?','Seek medical care and give nothing by mouth',['Give a laxative to relieve the pain','Apply a heating pad and wait','Have them eat a large meal'],'D','These are signs of possible appendicitis. Food, drink and laxatives can worsen the problem; get medical care.',DHO),
  q(MED,'A woman late in pregnancy feels faint while lying flat on her back. How should she be positioned?','On her left side',['Flat with legs raised','Face down on the floor','Sitting with head between knees'],'A','Lying on the back lets the uterus press on the vena cava, lowering blood flow to the heart; the left side relieves this.',AHA_FA),
  q(MED,'A 6-week-old infant has a temperature of 100.6 °F (38.1 °C). What should be done?','Seek medical care promptly',['Wait 2 days to see if it passes','Give an adult dose of aspirin','Bathe the infant in cold water'],'B','Fever in an infant under 3 months can signal serious infection and needs prompt evaluation; aspirin is avoided in children.',AHA_FA),
  q(MED,'A friend says they plan to end their life tonight. What should a first aider do?','Stay with them and call 988 or 911',['Leave them alone to calm down','Promise to keep it a secret','Change the subject to lighten the mood'],'C','Take the statement seriously, do not leave the person alone, remove means if safe and get help through 988 or 911.',AHA_FA),
  q(MED,'A person having an allergic reaction has trouble breathing. Which position is usually most comfortable?','Sitting up',['Lying flat on the back','Lying face down','Standing and walking'],'D','Most people with breathing difficulty breathe more easily sitting up; lay them down only if they feel faint or are in shock.',AHA_FA),
  q(INJ,'A person has an unbroken blister on the heel from new shoes. Which care is recommended?','Leave it intact and cover it',['Pop it with a needle right away','Peel off the top layer of skin','Rub alcohol into it daily'],'A','Intact skin protects against infection. Cover with a soft bandage; if it breaks, wash it and cover it.',ARC_FA),
  q(INJ,'A person steps on a rusty nail. Why should they check their tetanus vaccine status?','Puncture wounds raise the risk of tetanus',['Rust itself always causes infection','The nail may contain lead poisoning','Tetanus shots stop all bleeding'],'B','Deep, dirty puncture wounds can harbor tetanus bacteria; a booster is often needed if the last dose was over 5 years ago.',DHO),
  q(INJ,'A scalp wound bleeds heavily, and you feel a soft, sunken area of the skull. How should pressure be applied?','Gently, around the edges of the wound',['Firmly, directly on the sunken area','Not at all, even if bleeding is heavy','With a tourniquet around the head'],'C','Pressing on a possible skull fracture can push bone fragments inward, so apply gentle pressure around the wound.',ARC_FA),
  q(INJ,'Blood soaks through the first dressing on a forearm wound. What should the first aider do?','Add more dressings on top and keep pressing',['Remove the soaked dressing and start over','Stop pressure to let the blood clot','Rinse the wound with water again'],'D','Removing a soaked dressing disturbs clots; add dressings and keep firm pressure, using a tourniquet if bleeding remains severe.',AHA_FA),
  q(INJ,'Which injury is a strain?','A stretched or torn muscle or tendon',['A stretched or torn ligament','A bone that has moved out of a joint','A crack in the shaft of a bone'],'A','Strains affect muscles or tendons; sprains affect ligaments, which connect bones at joints.',DHO),
  q(INJ,'A forearm fracture is being splinted. Which rule should be followed?','Immobilize the joints above and below',['Splint only the injured spot itself','Straighten the arm before splinting','Tie the splint as tight as possible'],'B','Immobilizing the wrist and elbow prevents movement of the broken bone; check circulation before and after splinting.',ARC_FA),
  q(INJ,'Which should NOT be put on a burn?','Butter, ice or home remedies',['Cool running water','A clean, dry dressing','Loose plastic wrap after cooling'],'C','Butter traps heat and raises infection risk, and ice can damage tissue; cool the burn with water and cover it loosely.',AHA_FA),
  q(INJ,'A child gets a black eye from a ball. Which care is recommended?','Apply a cold pack without pressing',['Press firmly on the eyeball','Apply a hot pack right away','Rinse the eye with soapy water'],'D','Cold reduces swelling; avoid pressure on the eye and seek care for vision changes, blood in the eye or severe pain.',ARC_FA),
  q(INJ,'Why should a person with a serious injury and signs of shock be kept warm?','The body loses heat easily in shock',['Warmth stops all internal bleeding','Heat raises blood sugar quickly','Being warm prevents fractures'],'A','Shock reduces circulation and the ability to stay warm; prevent heat loss with a blanket without overheating.',AHA_FA),
  q(ENV,'What is the most effective way to cool a person with exertional heat stroke?','Immerse them in cold water',['Give them warm fluids slowly','Fan them while fully clothed','Wrap them in a dry blanket'],'B','Cold-water immersion cools fastest; continue until EMS arrives or the person is cooled, and call 911.',AHA_FA),
  q(ENV,'Why should frostbitten skin NOT be rubbed?','Rubbing damages the frozen tissue',['Rubbing warms the skin too slowly','Rubbing spreads infection to the blood','Rubbing causes the skin to refreeze'],'C','Ice crystals in the tissue cut cells when rubbed; rewarm gently in warm water only if refreezing is unlikely.',AHA_FA),
  q(ENV,'A child is bitten by a neighbor’s dog, and the skin is broken. What should be done first?','Wash the wound well with soap and water',['Cover the bite without cleaning it','Apply a tourniquet above the bite','Wait to see if signs of rabies appear'],'D','Washing reduces infection and rabies risk; seek medical care, and report the bite so the animal can be checked.',ARC_FA),
  q(ENV,'A swimmer is stung on the foot by a stingray. Which care helps relieve the pain?','Soak the foot in hot water',['Pack the foot in ice','Rub sand into the wound','Apply vinegar for 30 seconds'],'A','Stingray venom is broken down by heat; soak in water as hot as tolerated and seek care for the wound.',ARC_FA),
  q(ENV,'A family wakes to find a bat flying in a child’s bedroom. What should they do?','Contact a healthcare provider about rabies',['Ignore it if no bite marks are seen','Release the bat and forget it','Apply antibiotic ointment to the child'],'B','Bat bites may be too small to see; anyone who may have been exposed while asleep should be evaluated for rabies treatment.',AHA_FA)
 ],6101)
};
